11	/**
12	 * Rejects a create request once 100 or more owners have already been created today,
13	 * counting existing owners whose registration date is today. Runs after
14	 * {@link ValidateOwnerFields}, so it sees the validated request, and before
15	 * {@link BuildOwner}, so an over-limit request is a 429 rather than a persisted record.
16	 */
17	public class CheckOwnerDailyLimit {
18	
19	    /** Reaching this many owners created today rejects further creates. */
20	    private static final int DAILY_LIMIT = 100;
21	
22	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
23	            throws OwnerDailyLimitExceededException {
24	        LocalDate effective = request.getRegistrationDate();
25	        if (effective == null) {
26	            effective = LocalDate.now();
27	        }
28	        // Count against the adjusted business day this create will land on, so the
29	        // limit matches the registrationDate BuildOwner will store (weekend rolled
30	        // forward to Monday) rather than the raw supplied or server date.
31	        LocalDate businessDay = BusinessDay.adjust(effective);
32	        int count = 0;
33	        for (Owner existing : ownerRepository.findAll()) {
34	            if (businessDay.equals(existing.getRegistrationDate())) {
35	                count++;
36	            }
37	        }
38	        if (count >= DAILY_LIMIT) {
39	            throw new OwnerDailyLimitExceededException(count);
40	        }
41	    }
42	}
